import { useId, useLayoutEffect, useRef, useState } from 'react';
import './TokenizedSearch.css';
export type Token = { id: string; label: string; editableText: string };
export type Suggestion = { id: string; label: string };
export type SearchValue = { tokens: Token[]; text: string };
export type SearchAction =
 | { type: 'search/textChanged'; text: string; selection: [number, number] }
 | { type: 'search/tokenRemoved'; id: string }
 | { type: 'search/tokenEditRequested'; id: string }
 | { type: 'search/suggestionAccepted'; suggestionId: string; replacingTokenId: string | null }
 | { type: 'search/cleared' }
 | { type: 'search/submitted' };
type Props = { value: SearchValue; suggestions: Suggestion[]; editingTokenId: string | null; dispatch: (action: SearchAction) => void; restoreSelection?: { revision: number; start: number; end: number } };
export function TokenizedSearch({ value, suggestions, editingTokenId, dispatch, restoreSelection }: Props) {
 const id = useId();
 const input = useRef<HTMLInputElement>(null);
 const [active, setActive] = useState(-1);
 const [expanded, setExpanded] = useState(false);
 const [announcement, setAnnouncement] = useState('');
 const savedCaret = useRef<[number, number]>([0, 0]);
 const chosen = expanded && active >= 0 ? suggestions[active] : undefined;
 useLayoutEffect(() => { if (restoreSelection) { input.current?.focus(); input.current?.setSelectionRange(restoreSelection.start, restoreSelection.end); } }, [restoreSelection]);
 const restore = () => { input.current?.focus(); input.current?.setSelectionRange(...savedCaret.current); };
 const accept = (suggestion: Suggestion) => { dispatch({ type: 'search/suggestionAccepted', suggestionId: suggestion.id, replacingTokenId: editingTokenId }); setAnnouncement((editingTokenId ? 'Replaced filter with ' : 'Added filter ') + suggestion.label); setExpanded(false); setActive(-1); restore(); };
 return <form role="search" aria-label="Workspace search" onSubmit={event => { event.preventDefault(); dispatch({ type: 'search/submitted' }); }}>
 <label htmlFor={id}>Search workspace</label>
 <div className="token-search" role="group" aria-label="Search text and filters">
 {value.tokens.map(token => <span className="search-token" key={token.id}><button type="button" aria-label={'Edit filter ' + token.label} onClick={() => { dispatch({ type: 'search/tokenEditRequested', id: token.id }); setAnnouncement('Editing filter ' + token.label); input.current?.focus(); }}>{token.label}</button><button type="button" aria-label={'Remove filter ' + token.label} onClick={() => { dispatch({ type: 'search/tokenRemoved', id: token.id }); setAnnouncement('Removed filter ' + token.label); restore(); }}>×</button></span>)}
 <input id={id} ref={input} type="search" value={value.text} role="searchbox" aria-label={editingTokenId ? 'Edit search filter' : 'Search workspace'}
 aria-autocomplete="list" aria-controls={expanded ? id + '-suggestions' : undefined} aria-activedescendant={chosen ? id + '-option-' + active : undefined} aria-describedby={id + '-help'}
 onSelect={event => { const node = event.currentTarget; savedCaret.current = [node.selectionStart ?? 0, node.selectionEnd ?? 0]; }}
 onFocus={() => setExpanded(true)}
 onChange={event => { setActive(-1); setExpanded(true); dispatch({ type: 'search/textChanged', text: event.target.value, selection: [event.target.selectionStart ?? 0, event.target.selectionEnd ?? 0] }); }}
 onKeyDown={event => { if (event.nativeEvent.isComposing) return; if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { if (!suggestions.length) return; event.preventDefault(); setExpanded(true); setActive(index => event.key === 'ArrowDown' ? (index + 1) % suggestions.length : (index - 1 + suggestions.length) % suggestions.length); } else if (event.key === 'Escape') { setExpanded(false); setActive(-1); } else if (event.key === 'Enter' && chosen) { event.preventDefault(); accept(chosen); } else if (event.key === 'Backspace' && !value.text && value.tokens.length) { event.preventDefault(); const token = value.tokens[value.tokens.length - 1]; dispatch({ type: 'search/tokenEditRequested', id: token.id }); setAnnouncement('Editing filter ' + token.label); } }} />
 <button type="button" onClick={() => { dispatch({ type: 'search/cleared' }); savedCaret.current = [0,0]; setAnnouncement('Search cleared'); restore(); }}>Clear search</button></div>
 <p id={id + '-help'}>Use arrow keys to browse suggestions and Enter to select. Tab to edit or remove filters. Backspace in empty text edits the last filter.</p>
 {expanded && <ul id={id + '-suggestions'} role="listbox" aria-label="Search suggestions">{suggestions.map((suggestion,index) => <li key={suggestion.id} id={id + '-option-' + index} role="option" aria-selected={chosen?.id === suggestion.id} onPointerDown={event => event.preventDefault()} onClick={() => accept(suggestion)}>{suggestion.label}</li>)}</ul>}
 <span role="status" className="sr-only">{announcement}</span>
 </form>;
}
// Parsing, suggestion generation, token order, editing drafts, replacement and persistence
// belong to the application reducer. After an accepted action it can supply restoreSelection
// with a new revision and the caret range appropriate to its resulting text.

