.token-search{display:flex;flex-wrap:wrap;align-items:center;gap:6px;border:1px solid #747d8b;border-radius:8px;padding:6px}
.token-search:focus-within{outline:2px solid #255ec9}
.token-search input{min-width:8ch;flex:1 1 140px;border:0;padding:8px;font:inherit}
.search-token{display:inline-flex;max-width:100%;border:1px solid #747d8b;border-radius:4px}
.search-token button{background:#edf2ff;border:0;padding:6px;overflow-wrap:anywhere}
[role=listbox]{list-style:none;padding:4px;border:1px solid #747d8b;max-height:240px;overflow:auto}
[role=option]{padding:8px;cursor:pointer}
[role=option][aria-selected=true]{background:#e1eaff;outline:1px solid #255ec9}
.token-search button:focus-visible{outline:2px solid #255ec9}
.sr-only{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden}
